def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    if n == 1:
        if history[0][1] == 'C':
            return 'C'
        return 'D'

    my_last, opp_last = history[-1]

    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if b == 'C':
                dc += 1
            else:
                dd += 1

    opp_def = cd + dd
    my_def = dc + dd
    opp_c = cc + dc

    last5 = history[-5:]
    last10 = history[-10:]

    opp_def5 = 0
    opp_def10 = 0
    dc10 = 0
    cd10 = 0
    for a, b in last10:
        if b == 'D':
            opp_def10 += 1
        if a == 'D' and b == 'C':
            dc10 += 1
        if a == 'C' and b == 'D':
            cd10 += 1
    for a, b in last5:
        if b == 'D':
            opp_def5 += 1

    if n >= 95:
        counts_c = [0, 0, 0, 0]
        counts_d = [0, 0, 0, 0]
        idx = {'CC': 0, 'CD': 1, 'DC': 2, 'DD': 3}

        for i in range(1, n):
            a0, b0 = history[i - 1]
            si = idx[a0 + b0]
            if history[i][1] == 'C':
                counts_c[si] += 1
            else:
                counts_d[si] += 1

        g = opp_c / float(n)
        priors = [
            0.82 + 0.1 * g,
            0.5 + 0.2 * g,
            0.2 + 0.2 * g,
            0.15 + 0.15 * g
        ]
        for i in range(4):
            if priors[i] > 0.92:
                priors[i] = 0.92
            if priors[i] < 0.08:
                priors[i] = 0.08

        alpha = 5.0
        p = []
        for i in range(4):
            c = counts_c[i]
            d = counts_d[i]
            p.append((c + alpha * priors[i]) / (c + d + alpha))

        cur_idx = idx[history[-1][0] + history[-1][1]]
        rem = 100 - n

        V = [[0.0, 0.0, 0.0, 0.0]]
        for step in range(1, rem + 1):
            prevV = V[-1]
            newV = [0.0, 0.0, 0.0, 0.0]
            for si in range(4):
                pk = p[si]
                one = 1.0 - pk
                valC = pk * (3.0 + prevV[0]) + one * (0.0 + prevV[1])
                valD = pk * (5.0 + prevV[2]) + one * (1.0 + prevV[3])
                if valC >= valD:
                    newV[si] = valC
                else:
                    newV[si] = valD
            V.append(newV)

        prevV = V[rem - 1]
        pk = p[cur_idx]
        one = 1.0 - pk
        valC = pk * (3.0 + prevV[0]) + one * (0.0 + prevV[1])
        valD = pk * (5.0 + prevV[2]) + one * (1.0 + prevV[3])

        if valC >= valD:
            return 'C'
        return 'D'

    if n >= 8:
        if opp_def10 >= 7:
            return 'D'
        if opp_def * 20 >= n * 7 and dc <= 1:
            return 'D'
        if opp_def * 10 >= n * 3 and cd10 >= 5 and dc10 == 0:
            return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_def10 <= 2 and opp_def <= max(1, n // 4):
                return 'C'
            if dc > dd and opp_def <= max(4, n // 2):
                return 'C'
            if opp_def10 == 0:
                return 'C'
            return 'D'
        else:
            if opp_def10 <= 1 and opp_def <= max(2, n // 5):
                return 'C'
            if opp_def <= max(1, n // 25):
                return 'C'
            if opp_def10 <= 3 and opp_def * 2 <= n and rng.random() < 0.2:
                return 'C'
            return 'D'
    else:
        if my_last == 'D':
            if dc >= 2 and dc > dd and opp_def <= max(4, n // 2):
                return 'D'
            if opp_def == 0:
                return 'D'
            if opp_def10 <= 1 and dc >= 1 and opp_def <= max(3, n // 4):
                return 'D'
            if dc10 >= 2 and dc10 > cd10 and opp_def <= max(4, n // 2):
                return 'D'
            return 'C'
        else:
            if opp_def == 0 and n > 25:
                return 'D'
            if opp_def10 == 0 and dc >= 2:
                return 'D'
            if opp_def5 == 0 and dc >= 1 and opp_def <= max(2, n // 4):
                return 'D'
            if dc >= 4 and dc > dd + 2 and opp_def * 4 <= n:
                return 'D'
            if opp_def10 >= 6:
                return 'D'
            return 'C'
